"""
Python-Skript A1L.py
Lösung zur Aufgabe A1
"""

# Definition von Variablen und Zuweisungen:
a = 1   # Die Variablen a, b und c werden mit den  Werten: 1
b = 2   # 2 und 
c = 3   # 3 belegt

# 1. Berechnung:
a_mal_c = a * c    #  a * c und b / c werden ausgerechnet und den 
b_durch_2 = b / 2  #  Variablen a_mal_c und b_durch_2 zugewiesen

print("a = ", a, ", b = ", b, ", c = ", c, sep = '') # Ausgabe von a, b und c
print("a*c = ", a_mal_c)   # Ausgabe von a_mal_c auf die Konsole
print("b/2 = ", b_durch_2) # Ausgabe von b_durch_2 auf die Konsole

# Zuweisung von neuen Werten:
a = -10  # Die Variablen a, b und c werden mit neuen  Werten -10
b = 100  # 100 und
c = -35  # -35 belegt

# 2. Berechnung:
a_mal_c = a * c    # a * c und b / c werden erneut ausgerechnet und den
b_durch_2 = b / 2  # Variablen a_mal_c und b_durch_2 zugewiesen

print("a = ", a, ", b = ", b, ", c = ", c, sep = '') # Ausgabe von a, b und c
print("a*c = ", a_mal_c)   # Ausgabe von a_mal_c
print("b/2 = ", b_durch_2) # Ausgabe von b_durch_2

print(41*'_' + "\nDas Programm ist erfolgreich beendet!")
